/// Builds a handle of the class `json_type` names, or a plain kind handle for another type.
pub(crate) fn from_json_type(
    py: Python<'_>,
    spec: ComponentSpec,
    json_type: Option<&str>,
) -> PyResult<Py<Normalizer>> {
    match json_type {
        Some("Lowercase") => Normalizer::concrete_component(py, spec, Lowercase),
        Some("ByteLevel") => Normalizer::concrete_component(py, spec, ByteLevel),
        Some("StripAccents") => Normalizer::concrete_component(py, spec, StripAccents),
        Some("NFC") => Normalizer::concrete_component(py, spec, Nfc),
        Some("NFD") => Normalizer::concrete_component(py, spec, Nfd),
        Some("NFKC") => Normalizer::concrete_component(py, spec, Nfkc),
        Some("NFKD") => Normalizer::concrete_component(py, spec, Nfkd),
        Some("Nmt") => Normalizer::concrete_component(py, spec, Nmt),
        Some("Replace") => Normalizer::concrete_component(py, spec, Replace),
        Some("Precompiled") => Normalizer::concrete_component(py, spec, Precompiled),
        Some("BertNormalizer") => Normalizer::concrete_component(py, spec, BertNormalizer),
        Some("Strip") => Normalizer::concrete_component(py, spec, Strip),
        Some("Prepend") => Normalizer::concrete_component(py, spec, Prepend),
        Some("MetaspaceNormalizer") => {
            Normalizer::concrete_component(py, spec, MetaspaceNormalizer)
        }
        _ => Normalizer::default_component(py, spec),
    }
}

